public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(TradeOpenTradeAgreementJournalHeaderV2Entity, GUPPriceComponentCodePriceAttributeGroupCombination))
    {
        if (this.PriceComponentCombination)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination combination = _dataSourceCtx.getBuffer();
            GUPPriceComponentCode componentCode;
            select firstonly componentCode where componentCode.PriceComponent == GUPPriceComponent::SalesTradeAgreement;
            combination.PriceComponentCodeName = componentCode.Name;
        }
    }
    return next insertEntityDataSource(_entityCtx, _dataSourceCtx);
}

public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next initializeEntityDataSource(_entityCtx, _dataSourceCtx);
    if (_dataSourceCtx.name() ==  dataEntityDataSourceStr(TradeOpenTradeAgreementJournalHeaderV2Entity, GUPPriceComponentCodePriceAttributeGroupCombination))
    {
        _dataSourceCtx.setDataSaved(true);
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
    }
}
